import java.nio.charset.*;import java.nio.file.*;import java.sql.*;import java.util.regex.*;
public class AuditXwgFields{public static void main(String[]a)throws Exception{String y=Files.readString(Path.of("src/main/resources/application.yml"),StandardCharsets.UTF_8);try(Connection c=DriverManager.getConnection(v(y,"url").replace("192.168.3.5","127.0.0.1"),v(y,"username"),v(y,"password"));var s=c.createStatement()){String q="SELECT COUNT(*) total, SUM(school_type IS NULL OR school_type='') no_type, SUM(tuition_min IS NULL) no_fee, SUM(curriculum IS NULL OR curriculum='') no_curriculum, SUM(grades IS NULL OR grades='') no_grades, SUM(district IS NULL OR district='') no_district, SUM(address IS NULL OR address='') no_address, SUM(official_website IS NULL OR official_website='') no_web, SUM(logo_url IS NULL OR logo_url='') no_logo, SUM(boarding_info IS NULL OR boarding_info='') no_boarding, SUM(class_size IS NULL OR class_size='') no_class, SUM(teacher_ratio IS NULL OR teacher_ratio='') no_ratio, SUM(student_count IS NULL) no_students, SUM(founding_time IS NULL OR founding_time='') no_founded FROM school WHERE xueweigui_school_id IS NOT NULL";try(var r=s.executeQuery(q)){r.next();for(int i=1;i<=15;i++)System.out.print((i==1?"":"\t")+r.getString(i));System.out.println();}try(var r=s.executeQuery("SELECT school_type,COUNT(*) FROM school WHERE xueweigui_school_id IS NOT NULL GROUP BY school_type ORDER BY school_type")){while(r.next())System.out.println("TYPE\t"+r.getString(1)+"\t"+r.getInt(2));}try(var r=s.executeQuery("SELECT COUNT(*) FROM school WHERE xueweigui_school_id IS NOT NULL AND tuition_min IS NOT NULL AND tuition_max IS NOT NULL")){r.next();System.out.println("FEE_COMPLETE\t"+r.getInt(1));}try(var r=s.executeQuery("SELECT id,name,school_type,tuition_min,tuition_max,curriculum,grades,district,address FROM school WHERE xueweigui_school_id IS NOT NULL ORDER BY id LIMIT 8")){while(r.next())System.out.printf("SAMPLE\t%d\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s%n",r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9));}}}static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);m.find();String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}}
